contracts/bridge/BridgeMiddleware.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity 0.8.27;


import "../vendors/zksync/bridgehub/IBridgehub.sol";

import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ILiquidityManager} from "../interfaces/ILiquidityManager.sol";
import {IUSDVault} from "../interfaces/IUSDVault.sol";


contract BridgeMiddleware is AccessControl, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ERRORS


    // EVENTS
    event ShareMinted(address indexed sender, uint256 amount, uint256 shares);
    event CannonicalTxHash(bytes32 indexed canonicalTxHash);
    event Sweeped(address token, address to);
    event StakeAndBridge(address token, uint256 amount, uint256 ozUSDMinted, uint256 l2GasLimit, uint256 l2GasPerPubdataByteLimit, uint256 gasMinted);
    // VARIABLES

    bytes32 public constant WITHDRAW_ROLE = keccak256("WITHDRAW_ROLE");

    address public immutable native;
    uint256 public immutable chainId;

    /// @notice address of the bridgehub
    IBridgehub public immutable bridgehub;

    ILiquidityManager public immutable liquidityManager;
    IUSDVault public immutable ozUSDVault;


    constructor (
        address _nativeCoin,
        uint256 _chainId,
        address _bridgehub,
        address _admin,
        address _withdrawer,
        address _liquidityManager,
        address _ozUSDVault
    ) {
        require(_nativeCoin != address(0), "BridgeWrap: native coin address is zero");
        require(_bridgehub != address(0), "BridgeWrap: bridgehub address is zero");
        require(_admin != address(0), "BridgeWrap: admin address is zero");
        require(_withdrawer != address(0), "BridgeWrap: withdrawer address is zero");
        native = _nativeCoin;
        chainId = _chainId;
        bridgehub = IBridgehub(_bridgehub);
        liquidityManager = ILiquidityManager(_liquidityManager);
        ozUSDVault = IUSDVault(_ozUSDVault);
        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(WITHDRAW_ROLE, _withdrawer);
    }


    function stakeAndBridge(uint256 _l2GasLimit) external payable nonReentrant {
        uint256 sharesMinted = _stakeNative(msg.value);
        _bridgeNative(msg.sender, sharesMinted, _l2GasLimit, 800);
        emit StakeAndBridge(address(0), msg.value, 0, _l2GasLimit, 800, msg.value);
    }

    function stakeAndBridgeStable(address token, uint256 amount, uint256 _l2GasLimit) external payable nonReentrant {
        uint256 gasCost = l2TransactionBaseCost(tx.gasprice, _l2GasLimit, 800);
        uint256 neededEth = _convertToEthAmount(gasCost);
        require (msg.value >= neededEth, "BridgeWrap: not enough ETH to cover the gas cost");
        uint256 gasMinted = _stakeNative(neededEth);
        uint256 ozUSDMinted;
        if (token == ozUSDVault.asset()) {
            ozUSDMinted = _stakeDai(amount);
        } else {
            ozUSDMinted = _stakeStable(token, amount);
        }
        _bridgeErc20(msg.sender, address(ozUSDVault), ozUSDMinted, _l2GasLimit, 800, gasMinted);
        emit StakeAndBridge(token, amount, ozUSDMinted, _l2GasLimit, 800, gasMinted);
    }

    function sweepTokens(address token, address to) external onlyRole(WITHDRAW_ROLE) {
        IERC20(token).safeTransfer(to, IERC20(token).balanceOf(address(this)));
        emit Sweeped(token, to);
    }

    /// @notice estimate the cost of L2 tx in base token.
    /// @param _l1GasPrice The gas price on L1
    /// @param _l2GasLimit The estimated L2 gas limit
    /// @param _l2GasPerPubdataByteLimit The price for each pubdata byte in L2 gas
    /// @return The price of L2 gas in the base token
    function l2TransactionBaseCost(uint256 _l1GasPrice, uint256 _l2GasLimit, uint256 _l2GasPerPubdataByteLimit)
    public
    view
    returns (uint256)
    {
        return bridgehub.l2TransactionBaseCost(chainId, _l1GasPrice, _l2GasLimit, _l2GasPerPubdataByteLimit);
    }

    /// @notice estimate the cost of L2 tx in ETH.
    /// @param _l1GasPrice The gas price on L1
    /// @param _l2GasLimit The estimated L2 gas limit
    /// @param _l2GasPerPubdataByteLimit The price for each pubdata byte in L2 gas
    /// @return The price of L2 gas in the base token
    function l2TransactionEthCost(uint256 _l1GasPrice, uint256 _l2GasLimit, uint256 _l2GasPerPubdataByteLimit)
    external
    returns (uint256)
    {
        uint256 baseCost = l2TransactionBaseCost(_l1GasPrice, _l2GasLimit, _l2GasPerPubdataByteLimit);
        return _convertToEthAmount(baseCost);
    }

    function _convertToEthAmount(uint256 _baseTokenAmount) internal returns (uint256) {
        uint256 nativeCoinAmount = IERC20(native).totalSupply();
        uint256 lmValue = liquidityManager.virtualBalance();
        if (lmValue == 0) {
            return _baseTokenAmount;
        }
        return _baseTokenAmount * lmValue * 1_000_000 / (nativeCoinAmount * 950_000); // cover for swap slippage
    }

    function _bridgeNative (
        address _l2Receiver,
        uint256 _amount,
        uint256 _l2GasLimit,
        uint256 _l2GasPerPubdataByteLimit
    ) internal returns (bytes32 canonicalTxHash) {
        uint256 txCost = l2TransactionBaseCost(tx.gasprice, _l2GasLimit, _l2GasPerPubdataByteLimit);
        require(_amount > txCost, "BridgeWrap: not enough to cover the tx cost");
        bytes memory empty;
        IERC20(native).safeIncreaseAllowance(address(bridgehub.sharedBridge()), _amount);
        canonicalTxHash = bridgehub.requestL2TransactionDirect(
            L2TransactionRequestDirect({
                chainId: chainId,
                mintValue: _amount,
                l2Contract: _l2Receiver,
                l2Value: _amount - txCost,
                l2Calldata: empty,
                l2GasLimit: _l2GasLimit,
                l2GasPerPubdataByteLimit: _l2GasPerPubdataByteLimit,
                factoryDeps: new bytes[](0),
                refundRecipient: _l2Receiver // refund to the receiver
            })
        );
        emit CannonicalTxHash(canonicalTxHash);
    }

    /// Bridge ERC20 from L1 (Ethereum) to L2 (hyperchain)
    function _bridgeErc20(
        address _l2Receiver,
        address _token,
        uint256 _amount,
        uint256 _l2GasLimit,
        uint256 _l2GasPerPubdataByteLimit,
        uint256 _l2GasMinted
    ) internal returns (bytes32 canonicalTxHash) {

        address sharedBridge = address(bridgehub.sharedBridge());
        IERC20(_token).approve(sharedBridge, _amount);
        IERC20(native).safeIncreaseAllowance(sharedBridge, _l2GasMinted);

        bytes memory callData = _getDepositL2Calldata(_l2Receiver, _token, _amount);

        canonicalTxHash = bridgehub.requestL2TransactionTwoBridges(
            L2TransactionRequestTwoBridgesOuter({
                chainId: chainId,
                mintValue: _l2GasMinted,
                l2Value: 0,
                l2GasLimit: _l2GasLimit,
                l2GasPerPubdataByteLimit: _l2GasPerPubdataByteLimit,
                refundRecipient: _l2Receiver,
                secondBridgeAddress: sharedBridge,
                secondBridgeValue: 0,
                secondBridgeCalldata: callData
            })
        );
        emit CannonicalTxHash(canonicalTxHash);
    }

    /// @notice Generate a calldata for calling the deposit finalization on the L2 bridge contract
    function _getDepositL2Calldata(address _l2Receiver, address _l1Token, uint256 _amount)
    internal
    pure
    returns (bytes memory)
    {
        return abi.encode(_l1Token, _amount, _l2Receiver);
    }

    function _stakeNative (uint256 amount) internal returns (uint256 sharesMinted){
        sharesMinted = IERC20(native).balanceOf(address(this));
        // send ETH to liquidity manager to get shares (ozETH)
        liquidityManager.stake{value: amount}();
        sharesMinted = IERC20(native).balanceOf(address(this)) - sharesMinted;
        emit ShareMinted(msg.sender, amount, sharesMinted);
    }

    function _stakeDai (uint256 amount) internal returns (uint256) {
        // get DAI from user
        IERC20(ozUSDVault.asset()).safeTransferFrom(msg.sender, address(this), amount);
        // give allowance to the vault, this deposit is available only for DAI
        IERC20(ozUSDVault.asset()).safeIncreaseAllowance(address(ozUSDVault), amount);
        return ozUSDVault.deposit(amount, address(this));
    }

    function _stakeStable(address token, uint256 amount) internal returns (uint256) {
        // get token from user
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
        // give allowance to the vault for the token stable that vault supports, otherwise fails
        IERC20(token).safeIncreaseAllowance(address(ozUSDVault), amount);
        return ozUSDVault.depositToken(token, amount, address(this));

    }

}

contracts/core/ozUSDVault.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity 0.8.27;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC4626} from "@openzeppelin/contracts/interfaces/IERC4626.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IConverter} from "../vendors/SkyMoney/IConverter.sol";
import {Swap} from "./Swap.sol";
import {IUSDVault} from "../interfaces/IUSDVault.sol";

contract ozUSDVault is IUSDVault, ReentrancyGuard, Ownable, ERC20 {
    using SafeERC20 for IERC20;

    event NewCliff(uint256 cliff);
    event NewFee(uint24 fee);
    event Withdrawn(address indexed owner, uint256 amount, uint256 index);
    event TokenAllowed(address indexed token, bool allowed);
    event QueueWithdraw(
        address indexed owner,
        address indexed receiver,
        uint256 shares,
        uint256 amountReceived,
        address asset,
        uint256 cliff,
        uint256 index
    );

    struct Queue {
        uint256 amount;
        address receiver;
        address owner;
        uint256 cliff;
        bool processed;
        address asset;
    }

    uint256 public nextWithdrawIndex;
    mapping(uint256 => Queue) public withdrawQueue;

    uint24 private _fee;
    address private immutable _self;
    address public immutable _underlying;
    address public immutable _univ3router; // 0x68b3465833fb72A70ecDF485E0e4C7bD8665Fc45 for mainnet

    address public immutable sUSDSVault; // 0xa3931d71877C0E7a3148CB7Eb4463524FEc27fbD for mainnet
    address public immutable _asset;
    address public immutable converter; // 0x3225737a9Bbb6473CB4a45b7244ACa2BeFdB276A for mainnet
    uint256 public _cliff = 3 days;
    mapping (address => bool) public isAllowedToken; // initialized with DAI underlying as allowed

    // modifiers

    modifier onlyAllowedToken(address token) {
        require(isAllowedToken[token], "onlyAllowedToken: token not allowed");
        _;
    }

    constructor(
        address underlying,
        address owner,
        uint24 fee,
        address sUSDSVault_,
        address converter_,
        address uniV3Router
    ) ERC20("ozUSD", "ozUSD") Ownable(owner) {
        require(underlying != address(0), "sv: underlying 0");
        require(owner != address(0), "v: owner 0");
        require(sUSDSVault_ != address(0), "v: vault 0");
        require(converter_ != address(0), "v: converter 0");
        require(uniV3Router != address(0), "v: router 0");
        sUSDSVault = sUSDSVault_;
        converter = converter_;
        _underlying = underlying; // DAI for example
        _asset = IERC4626(sUSDSVault).asset(); // USDS
        _self = address(this);
        _fee = fee;
        _univ3router = uniV3Router;
        isAllowedToken[_underlying] = true;
    }

    function allowToken(address token, bool allow) external onlyOwner {
        require(token != address(0), "allowToken: token cannot be zero address");
        isAllowedToken[token] = allow;
        emit TokenAllowed(token, allow);
    }

    function deposit(
        uint256 assets,
        address receiver
    ) external nonReentrant returns (uint256 shares) {
        require(assets > 0, "deposit: amount must be greater than 0");

        // Transfer underlying to the vault
        IERC20(_underlying).safeTransferFrom(_msgSender(), _self, assets);
        return _depositUnderlying(assets, receiver);
    }

    function depositToken(
        address token,
        uint256 assets,
        address receiver
    ) external nonReentrant onlyAllowedToken(token) returns (uint256 shares) {
        require(assets > 0, "deposit: amount must be greater than 0");

        // Transfer tokens to the vault
        IERC20(token).safeTransferFrom(_msgSender(), _self, assets);
        IERC20(token).safeIncreaseAllowance(_univ3router, assets);
        uint256 amountReceived = Swap.swap(
            _univ3router,
            _fee,
            token,
            _underlying,
            _self,
            assets,
            0
        );

        shares = _depositUnderlying(amountReceived, receiver);
    }

    function queueWithdraw(
        uint256 shares
    ) external returns (uint256 index, uint256 cliff) {
        require(shares > 0, "queueWithdraw: shares must be greater than 0");
        uint256 dai = _beginQueue(shares);
        require(dai > 0, "queueWithdraw: swapped dia must be greater than 0");
        emit QueueWithdraw(
            _msgSender(),
            _msgSender(),
            shares,
            dai,
            _underlying,
            block.timestamp + _cliff,
            nextWithdrawIndex
        );
        return
            _queueWithdrawToken(dai, _msgSender(), _msgSender(), _underlying);
    }

    function queueWithdrawToken(
        uint256 shares,
        address token
    ) external onlyAllowedToken(token) returns (uint256 index, uint256 cliff) {
        require(
            shares > 0,
            "queueWithdrawToken: shares must be greater than 0"
        );

        // returns the DAI amount we got out of sUSDS Vault
        uint256 dai = _beginQueue(shares);

        // approve dai to uni V3 Router
        IERC20(_underlying).safeIncreaseAllowance(_univ3router, dai);
        // Swap DAI to the token we want it out into
        uint256 amountSwapped = Swap.swapWithMaximumSlippage(
            _univ3router,
            _fee,
            _underlying,
            token,
            _self,
            dai
        );
        emit QueueWithdraw(
            _msgSender(),
            _msgSender(),
            shares,
            amountSwapped,
            token,
            block.timestamp + _cliff,
            nextWithdrawIndex
        );
        return
            _queueWithdrawToken(
                amountSwapped,
                _msgSender(),
                _msgSender(),
                token
            );
    }

    function withdraw(uint256 index) external returns (uint256 amount) {
        require(
            withdrawQueue[index].owner == _msgSender(),
            "withdraw: only account owner can withdraw"
        );

        Queue storage queue = withdrawQueue[index];
        require(queue.amount > 0, "withdraw: amount must be greater than 0");
        require(
            queue.cliff <= block.timestamp,
            "withdraw: cliff not reached yet"
        );
        require(!queue.processed, "withdraw: already processed");

        queue.processed = true;
        amount = queue.amount;

        IERC20(queue.asset).safeTransfer(queue.receiver, amount);
        emit Withdrawn(_msgSender(), amount, index);
    }

    /**
     * @notice Set the new cliff
     * @param cliff The new cliff
     */
    function setNewCliff(uint256 cliff) external onlyOwner {
        _cliff = cliff;
        emit NewCliff(cliff);
    }

    /**
     * @notice Set the new fee
     * @param fee The new fee
     */
    function setNewFee(uint24 fee) external onlyOwner {
        _fee = fee;
        emit NewFee(fee);
    }

    function getFee() external view returns (uint256) {
        return _fee;
    }

    function asset() external view returns (address) {
        return _underlying;
    }

    function canWithdraw(uint256 index) external view returns (bool) {
        Queue memory queue = withdrawQueue[index];
        return
            queue.amount > 0 &&
            queue.cliff <= block.timestamp &&
            !queue.processed;
    }

    // Burn shares and swap back to underlying DAI
    function _beginQueue(uint256 shares) private returns (uint256) {
        _burn(_msgSender(), shares);

        // Withdraw underlying asset usds from sUSDSVault
        uint256 assetsBefore = IERC20(_asset).balanceOf(_self);

        uint256 usds = IERC4626(sUSDSVault).redeem(shares, _self, _self);

        uint256 assetsAfter = IERC20(_asset).balanceOf(_self);
        uint256 assets = assetsAfter - assetsBefore;
        require(assets > 0, "_beginQueue: assets must be greater than 0");

        // Swap asset to underlying DAI
        uint256 underlyingBefore = IERC20(_underlying).balanceOf(_self);
        IERC20(_asset).safeIncreaseAllowance(converter, usds);
        IConverter(converter).usdsToDai(_self, usds);
        uint256 underlyingAfter = IERC20(_underlying).balanceOf(_self);
        uint256 swappedAmount = underlyingAfter - underlyingBefore;

        return swappedAmount;
    }

    function _queueWithdrawToken(
        uint256 amount,
        address receiver,
        address owner,
        address token
    ) private returns (uint256 index, uint256 cliff) {
        cliff = block.timestamp + _cliff;
        Queue memory queue = Queue({
            amount: amount,
            receiver: receiver,
            owner: owner,
            cliff: cliff,
            processed: false,
            asset: token
        });

        index = nextWithdrawIndex;
        withdrawQueue[index] = queue;

        unchecked {
            nextWithdrawIndex++;
        }
    }

    function _depositUnderlying(
        uint256 assets,
        address receiver
    ) private returns (uint256 shares) {
        // Swap underlying to asset
        uint256 usdsBefore = IERC20(_asset).balanceOf(_self);

        IERC20(_underlying).safeIncreaseAllowance(converter, assets);
        IConverter(converter).daiToUsds(_self, assets);
        uint256 usdsAfter = IERC20(_asset).balanceOf(_self);

        uint256 swappedAmount = usdsAfter - usdsBefore;
        require(
            swappedAmount > 0,
            "deposit: swapped amount must be greater than 0"
        );

        // Approve sUSDSVault to spend swappedAmount
        IERC20(_asset).safeIncreaseAllowance(sUSDSVault, swappedAmount);

        uint256 sharesBefore = IERC20(sUSDSVault).balanceOf(_self);
        IERC4626(sUSDSVault).deposit(swappedAmount, _self);
        uint256 sharesAfter = IERC20(sUSDSVault).balanceOf(_self);

        require(sharesAfter > sharesBefore, "_depositUnderlying: invalid received shares");
        shares = sharesAfter - sharesBefore;
        require(shares > 0, "_depositUnderlying: shares must be greater than 0");

        _mint(receiver, shares);
    }
}

contracts/core/Swap.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity 0.8.27;

import {ISwapRouter} from "../vendors/Uniswap/ISwapRouter.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";

library Swap {
    uint256 constant SLIPPAGE_TOLERANCE = 997_000; // 99.7%
    uint256 constant SCALE = 1_000_000;

    function approveAndSwap(
        address router,
        uint24 fee,
        address tokenIn,
        address tokenOut,
        address recipient,
        uint256 amountIn
    ) internal returns (uint256 amountOut) {
        IERC20(tokenIn).approve(router, amountIn);
        amountOut = swapWithMaximumSlippage(
            router,
            fee,
            tokenIn,
            tokenOut,
            recipient,
            amountIn
        );
    }

    function swap(
        address router,
        uint24 fee,
        address tokenIn,
        address tokenOut,
        address recipient,
        uint256 amountIn,
        uint256 amountOutMinimum
    ) internal returns (uint256 amountOut) {
        ISwapRouter swapRouter = ISwapRouter(router);

        // Naively set amountOutMinimum to 0. In production, use an oracle or other data source to choose a safer value for amountOutMinimum.
        // We also set the sqrtPriceLimitx96 to be 0 to ensure we swap our exact input amount.
        ISwapRouter.ExactInputSingleParams memory params = ISwapRouter
            .ExactInputSingleParams({
                tokenIn: tokenIn,
                tokenOut: tokenOut,
                fee: fee,
                recipient: recipient, // send back to the caller
                amountIn: amountIn,
                amountOutMinimum: amountOutMinimum,
                sqrtPriceLimitX96: 0
            });

        // The call to `exactInputSingle` executes the swap.
        amountOut = swapRouter.exactInputSingle(params);
    }

    function swapWithMaximumSlippage(
        address router,
        uint24 fee,
        address tokenIn,
        address tokenOut,
        address recipient,
        uint256 amountIn
    ) internal returns (uint256 amountOut) {
        uint256 tokenInDecimals = IERC20Metadata(tokenIn).decimals();
        uint256 tokenOutDecimals = IERC20Metadata(tokenOut).decimals();

        // Normalize amounts based on decimal differences
        uint256 normalizedAmountIn = amountIn;
        if (tokenOutDecimals > tokenInDecimals) {
            normalizedAmountIn = amountIn * (10 ** (tokenOutDecimals - tokenInDecimals));
        }

        // Calculate minimum amount out with slippage
        uint256 amountOutMinimum = normalizedAmountIn * SLIPPAGE_TOLERANCE / SCALE;

        // If output token has fewer decimals, adjust the minimum amount
        if (tokenInDecimals > tokenOutDecimals) {
            amountOutMinimum = amountOutMinimum / (10 ** (tokenInDecimals - tokenOutDecimals));
        }

        amountOut = swap(
            router,
            fee,
            tokenIn,
            tokenOut,
            recipient,
            amountIn,
            amountOutMinimum
        );
    }

    function swapWithMaximumSlippageRETH(
        address router,
        uint24 fee,
        address tokenIn,
        address tokenOut,
        address recipient,
        uint256 amountIn,
        uint256 amountOutMinimum
    ) internal returns (uint256 amountOut) {
        amountOut = swap(
            router,
            fee,
            tokenIn,
            tokenOut,
            recipient,
            amountIn,
            amountOutMinimum
        );
    }

    function _swapWithMultipleHops(
        ISwapRouter swapRouter,
        bytes calldata _path,
        address _recipient,
        uint256 _amountIn,
        uint256 _amountOutMinimum
    ) internal returns (uint256 amountOut){

        ISwapRouter.ExactInputParams memory params =
                            ISwapRouter.ExactInputParams({
                path: _path,
                recipient: _recipient,
                amountIn: _amountIn,
                amountOutMinimum: _amountOutMinimum
            });
        // The call to `exactInputSingle` executes the swap.
        amountOut = swapRouter.exactInput(params);
    }
}

